#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
#include "session_render_scene_candidate.h"
#include <iostream>
int main(int argc,char**argv){try{static_assert(sizeof(void*)==8,"x64 required");if(argc!=2)throw std::runtime_error("session required");auto graph=loadGraph(argv[1]);size_t shots=0,models=0,multi=0;for(uint32_t id=0;id<graph.elements.size();++id){auto&e=graph.elements[id];if(graph.strings.at(e.type)!="DmeFilmClip"||hierarchyRefs(graph,e,"camera",1).empty())continue;auto scene=readSessionRenderSceneCandidate(graph,id,512,512);auto binding=readFilmSceneRenderBindingCandidate(graph,id);if(scene.models.size()!=binding.models.size())throw std::runtime_error("scene lost models");std::cout<<"shot="<<id<<" models="<<scene.models.size()<<"\n";for(size_t n=0;n<scene.models.size();++n){auto&m=scene.models[n];if(m.id!=binding.models[n])throw std::runtime_error("scene order");std::cout<<" model="<<m.id<<" visible="<<m.visible<<" skin="<<m.skin<<" body="<<m.body<<" asset="<<m.placement.asset<<"\n";}++shots;models+=scene.models.size();multi+=scene.models.size()>1;}if(!shots||!multi)throw std::runtime_error("multi-model coverage missing");std::cout<<"scene extraction passed shots="<<shots<<" model_instances="<<models<<" multi_model_shots="<<multi<<" gpu_multi_model=unfinished native_parity=unverified\n";return 0;}catch(std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
